{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Imatinib, which shares the anilino-pyrimidine and basic piperazine motif, has a mean absolute oral bioavailability of 98% in humans, demonstrating that this chemotype can be very well absorbed despite ionizable basic nitrogen.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Niraparib, a structurally related oral anticancer agent with a basic center, has an absolute oral bioavailability of approximately 73% in patients, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Trametinib, a larger and polar oral kinase inhibitor, has an absolute bioavailability of 72% in humans, showing that high molecular weight and polar surface area do not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brepocitinib, a heteroaromatic kinase inhibitor with piperazine/piperidine-like features, has an estimated absolute bioavailability of 75% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "GSK1322322, containing a piperazine and aminopyrimidine core, has an absolute bioavailability of 57% in the fasted state in healthy volunteers, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Risdiplam, a heteroaromatic oral drug with high oral bioavailability in humans, supports the pattern that this structural class can achieve high F despite complex polar functionality.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High. Although the physicochemical prior flags low neutral fraction and high TPSA, multiple human absolute-bioavailability studies in structurally related heteroaromatic/piperazine-containing kinase inhibitors show F values of 57–98%, all well above the 20% threshold. The consistent experimental direction outweighs the uncertain prior, so the query is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarities to evidence compounds are low, limiting direct structural transferability.",
    "No human PK, permeability, efflux, or metabolic stability data are available for the query.",
    "The physicochemical prior is uncertain and does not account for possible active transport or other absorption mechanisms."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

